struct Book { author_id: i64, author: OnceLock<Result<Author, StoreError>> }

impl Book {
    fn author(&self) -> Result<&Author, &StoreError> {
        self.author
            .get_or_init(|| load_author(self.author_id))   // once
            .as_ref()
    }
}

